<?php
declare(strict_types=1);
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/cashier-view.php';require_once __DIR__.'/../includes/system-settings.php';
$user=snc_require_auth(['admin']);$csrfToken=snc_csrf_token();header('Cache-Control: no-store');$error='';$settings=null;$flash=snc_pop_flash();
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        if(!snc_verify_csrf(is_string($_POST['csrf_token']??null)?$_POST['csrf_token']:null))throw new RuntimeException('Session expired. Refresh before saving.',403);
        $result=snc_settings_save(snc_get_db(),$user,$_POST);snc_set_flash('success',$result['message'],'System Settings');header('Location: settings.php',true,303);exit;
    }catch(InvalidArgumentException $e){http_response_code(422);$error=$e->getMessage();}
    catch(RuntimeException $e){$code=!($e instanceof PDOException)&&in_array($e->getCode(),[403,409],true)?$e->getCode():503;http_response_code($code);$error=$code===503?'Settings could not be saved. Refresh to check the current values.':$e->getMessage();}
}
try{$settings=snc_settings_get(snc_get_db());}catch(Throwable $e){http_response_code(503);$error='System settings are temporarily unavailable.';}
$values=$settings??snc_settings_defaults();
if($_SERVER['REQUEST_METHOD']==='POST'&&$error){
    foreach(['business_name','business_address','contact_number','receipt_header','receipt_footer','paper_width'] as $key)if(is_string($_POST[$key]??null))$values[$key]=$_POST[$key];
    foreach(['cash','gcash','card'] as $method)$values[$method.'_enabled']=is_array($_POST['methods']??null)&&in_array($method,$_POST['methods'],true)?1:0;
}
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>System Settings | SNC 2018 Café &amp; Resto</title><link rel="icon" type="image/svg+xml" href="../assets/images/snc-dreamcatcher-emblem.svg"><link rel="stylesheet" href="../assets/css/snc-tokens.css?v=1.0"><link rel="stylesheet" href="../assets/css/snc-navigation.css?v=1.1"><link rel="stylesheet" href="../assets/css/snc-dashboard.css?v=1.2"><link rel="stylesheet" href="../assets/css/snc-menu.css?v=1.4"><link rel="stylesheet" href="../assets/css/snc-settings.css?v=1.0"><link rel="stylesheet" href="../assets/css/snc-notifications.css?v=1.0"><script src="../assets/js/snc-navigation.js?v=1.0" defer></script><script src="../assets/js/snc-notifications.js?v=1.0" defer></script><script src="../assets/js/snc-settings.js?v=1.0" defer></script></head><body<?= $flash?' data-snc-flash="'.snc_cashier_escape(json_encode($flash)).'"':'' ?>><div class="snc-shell" id="snc-shell"><?php $adminPage='settings';require __DIR__.'/../includes/admin-shell.php'; ?><main class="snc-dashboard">
<section class="snc-dashboard__header"><div><h1 class="snc-dashboard__title">System Settings</h1><p class="snc-dashboard__subtitle">Business details, receipt defaults, and accepted payments.</p></div><a class="snc-menu-button" href="audit.php?activity=settings%3Aupdated">View Settings History</a></section>
<?php if($error): ?><p class="snc-menu-error" role="alert"><?= snc_cashier_escape($error) ?></p><?php endif; ?>
<?php if($settings): ?><div class="snc-settings-layout"><form id="snc-settings-form" method="post" class="snc-settings-form"><input type="hidden" name="csrf_token" value="<?= snc_cashier_escape($csrfToken) ?>"><input type="hidden" name="revision" value="<?= snc_cashier_escape($_SERVER['REQUEST_METHOD']==='POST'&&$error?(is_string($_POST['revision']??null)?$_POST['revision']:''):$settings['revision']) ?>">
<section class="snc-card"><h2 class="snc-card__title">Business Details</h2><p class="snc-menu-hint">Shown on receipts for new orders. Existing receipts retain their saved details.</p>
<label>Business name<input name="business_name" required maxlength="120" data-preview="business_name" value="<?= snc_cashier_escape($values['business_name']) ?>"></label>
<label>Address <span class="snc-settings-optional">Optional · up to 240 characters</span><textarea name="business_address" rows="2" maxlength="240" data-preview="business_address"><?= snc_cashier_escape($values['business_address']) ?></textarea></label>
<label>Contact number <span class="snc-settings-optional">Optional · up to 80 characters</span><input name="contact_number" maxlength="80" data-preview="contact_number" value="<?= snc_cashier_escape($values['contact_number']) ?>"></label></section>
<section class="snc-card"><h2 class="snc-card__title">Receipt Settings</h2><label>Header message <span class="snc-settings-optional">Optional · up to 240 characters</span><textarea name="receipt_header" rows="2" maxlength="240" data-preview="receipt_header"><?= snc_cashier_escape($values['receipt_header']) ?></textarea></label>
<label>Footer message <span class="snc-settings-optional">Optional · up to 240 characters</span><textarea name="receipt_footer" rows="2" maxlength="240" data-preview="receipt_footer"><?= snc_cashier_escape($values['receipt_footer']) ?></textarea></label>
<label>Default paper width<select name="paper_width" data-settings-width><option value="80"<?= $values['paper_width']==='80'?' selected':'' ?>>80 mm</option><option value="58"<?= $values['paper_width']==='58'?' selected':'' ?>>58 mm</option></select></label><p class="snc-menu-hint">Paper width applies to all receipt previews. Cashiers can adjust it for a single print. Printer paper and driver settings must match.</p></section>
<section class="snc-card"><h2 class="snc-card__title">Payment Methods</h2><p class="snc-menu-hint">Choose which payment methods cashiers can use for new orders. Keep at least one enabled.</p><fieldset class="snc-settings-payments"><legend class="snc-settings-legend">Accepted payment methods</legend><?php foreach(['cash'=>'Cash','gcash'=>'GCash','card'=>'Card'] as $method=>$label): ?><label><input type="checkbox" name="methods[]" value="<?= $method ?>"<?= (int)$values[$method.'_enabled']?' checked':'' ?>><?= $label ?></label><?php endforeach; ?></fieldset><p class="snc-menu-hint">Historical payments and reports keep their original method, including methods disabled later.</p></section>
<div class="snc-settings-save"><span class="snc-menu-hint">Changes are recorded in Audit Trail.</span><a class="snc-menu-button" href="settings.php">Discard Changes</a><button class="snc-menu-button snc-menu-button--primary" type="submit">Save Changes</button></div></form>
<aside class="snc-card snc-settings-preview"><h2 class="snc-card__title">Receipt Preview</h2><p class="snc-menu-hint">Example only · reflects unsaved text.</p><div class="snc-settings-paper" data-settings-paper data-width="<?= $values['paper_width']==='58'?'58':'80' ?>"><h3 data-receipt-preview="business_name"><?= snc_cashier_escape($values['business_name']) ?></h3><?php foreach(['receipt_header','business_address','contact_number'] as $key): ?><p data-receipt-preview="<?= $key ?>"><?= snc_cashier_escape($values[$key]) ?></p><?php endforeach; ?><p>TRANSACTION SUMMARY</p><hr><div class="snc-settings-sample-line"><span>Example item × 1</span><span>₱150.00</span></div><hr><div class="snc-settings-sample-line"><strong>Total</strong><strong>₱150.00</strong></div><hr><p>For inventory purposes only.<br>This is not an official receipt.</p><p>Please ask the cashier if you need an official receipt.</p><p data-receipt-preview="receipt_footer"><?= snc_cashier_escape($values['receipt_footer']) ?></p></div><p class="snc-menu-hint">Receipt text is saved with each new order. Paper width is a preview default.</p></aside></div><?php endif; ?>
</main></div></div></body></html>
